import argparse, struct, pefile, capstone
from pathlib import Path
p=argparse.ArgumentParser(); p.add_argument('ranges', nargs='*'); p.add_argument('--selftest',action='store_true'); args=p.parse_args()
b=Path(r'D:\tmp2b\fm24\input\editor.exe').read_bytes(); pe=pefile.PE(data=b, fast_load=True); base=pe.OPTIONAL_HEADER.ImageBase
md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_64); md.detail=True
va=lambda o:base+pe.get_rva_from_offset(o)
def off(a):
 s=pe.get_section_by_rva(a-base)
 if s is None or a-base-s.VirtualAddress>=s.SizeOfRawData:return None
 return s.PointerToRawData+a-base-s.VirtualAddress
def fmt(i):
 refs=[i.address+i.size+x.mem.disp for x in i.operands if x.type==capstone.x86.X86_OP_MEM and x.mem.base==capstone.x86.X86_REG_RIP]
 if i.group(capstone.CS_GRP_JUMP) or i.group(capstone.CS_GRP_CALL): refs += [x.imm for x in i.operands if x.type==capstone.x86.X86_OP_IMM]
 return f'{off(i.address):08x}  {i.bytes.hex(" "):28} {i.mnemonic:8} {i.op_str:38}'+' '.join(f'  -> {a:#x} (off {off(a) if off(a) is None else hex(off(a))})' for a in refs)
if args.selftest:
 assert va(0xe4f4d5)==0x140e4fed5
for arg in args.ranges or ['pe']:
 if arg=='pe':
  print(hex(base), 'entry',hex(pe.OPTIONAL_HEADER.AddressOfEntryPoint))
  for s in pe.sections:
   print(s.Name, *(hex(x) for x in (s.VirtualAddress,s.Misc_VirtualSize,s.PointerToRawData,s.SizeOfRawData,s.Characteristics)))
  print([(d.name,hex(d.VirtualAddress),hex(d.Size)) for d in pe.OPTIONAL_HEADER.DATA_DIRECTORY]); continue
 if arg.startswith('@'): 
  o,n=(int(x,16) for x in arg[1:].split(':')); print(hex(o),hex(va(o)),b[o:o+n].hex(' ')); continue
 o,*rest=(int(x,16) for x in arg.split(':')); end=rest[0] if rest else o+0x60
 for i in md.disasm(b[o:end],va(o)):
  print(fmt(i))

